const input = $('When Executed by Orchestrator').first().json;
const registry = $input.first().json; // Result of our own registry call, never caller data.
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const validIdentity = (input, server) => server?.enabled === true
  && input.user_authorization_verified === true && input.user_authorization_mode === 'entra_delegated'
  && typeof input.user_tid === 'string' && uuid.test(input.user_tid) && input.user_tid.toLowerCase() === server.tenant_id
  && typeof input.user_oid === 'string' && uuid.test(input.user_oid)
  && typeof input.user_sub === 'string' && input.user_sub.trim().length > 0
  && Number.isSafeInteger(input.user_token_expires_at) && input.user_token_expires_at > Math.floor(Date.now() / 1000)
  && Array.isArray(input.user_authorized_groups) && input.user_authorized_groups.every(g => typeof g === 'string' && uuid.test(g))
  && server.required_group_ids.some(g => input.user_authorized_groups.some(u => u.toLowerCase() === g));
const server = registry.servers?.find(s => s.server_name === 'jems');
if (!validIdentity(input, server)) throw new Error('MCP_ACCESS_DENIED');
if (input.server_name !== server.server_name) throw new Error('MCP_TOOL_DENIED');
const tool = server.tools.find(t => t.name === input.tool_name && t.enabled === true);
if (!tool) throw new Error('MCP_TOOL_DENIED');
// Small fail-closed checker for registered schemas; metadata is not identity policy.
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const own = (value, key) => Object.prototype.hasOwnProperty.call(value, key);
const unsupported = () => { throw new Error('MCP_SCHEMA_NOT_SUPPORTED'); };
const invalid = () => { throw new Error('MCP_ARGUMENTS_INVALID'); };
const keywords = new Set(['type', 'properties', 'required', 'items', 'enum', 'format',
  'additionalProperties', 'title', 'description', '$comment']);
const checkSchema = schema => {
  if (!object(schema) || Object.keys(schema).some(key => !keywords.has(key))) unsupported();
  if (!['object', 'array', 'string', 'integer'].includes(schema.type)) unsupported();
  if (own(schema, 'format') && !(schema.type === 'integer' && schema.format === 'int64')) unsupported();
  if (own(schema, 'enum') && (!Array.isArray(schema.enum) || !schema.enum.length
    || schema.enum.some(v => schema.type === 'string' ? typeof v !== 'string'
      : schema.type === 'integer' ? !Number.isSafeInteger(v) : true))) unsupported();
  if (schema.type === 'object') {
    if (own(schema, 'properties') && !object(schema.properties)) unsupported();
    if (own(schema, 'required') && (!Array.isArray(schema.required)
      || schema.required.some(key => typeof key !== 'string')
      || new Set(schema.required).size !== schema.required.length)) unsupported();
    if (own(schema, 'additionalProperties') && typeof schema.additionalProperties !== 'boolean'
      && !object(schema.additionalProperties)) unsupported();
    Object.values(schema.properties || {}).forEach(checkSchema);
    if (object(schema.additionalProperties)) checkSchema(schema.additionalProperties);
  } else if (own(schema, 'properties') || own(schema, 'required') || own(schema, 'additionalProperties')) unsupported();
  if (schema.type === 'array') {
    if (!object(schema.items)) unsupported();
    checkSchema(schema.items);
  } else if (own(schema, 'items')) unsupported();
};
const checkValue = (schema, value) => {
  if (schema.type === 'object') {
    if (!object(value)) invalid();
    const properties = schema.properties || {};
    if ((schema.required || []).some(key => !own(value, key))) invalid();
    for (const [key, child] of Object.entries(value)) {
      if (own(properties, key)) checkValue(properties[key], child);
      else if (object(schema.additionalProperties)) checkValue(schema.additionalProperties, child);
      // Conservative tool policy: omitted/true additionalProperties does not permit undeclared arguments.
      else invalid();
    }
  } else if (schema.type === 'array') {
    if (!Array.isArray(value)) invalid();
    value.forEach(child => checkValue(schema.items, child));
  } else if (schema.type === 'string') {
    if (typeof value !== 'string') invalid();
  } else if (!Number.isSafeInteger(value)) invalid(); // int64: only exactly representable safe integers.
  if (schema.enum && !schema.enum.includes(value)) invalid();
};
checkSchema(tool.inputSchema);
if (tool.inputSchema.type !== 'object') unsupported();
if (typeof input.tool_arguments !== 'string') invalid();
let args;
try { args = JSON.parse(input.tool_arguments); } catch { invalid(); }
// Reject integer lexemes that JSON.parse would round into a different safe integer.
// Strings are consumed whole so digits in dates, IDs or source text are not inspected.
for (const token of input.tool_arguments.match(/"(?:[^"\\]|\\.)*"|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?/g) || []) {
  if (token[0] === '"') continue;
  const value = Number(token);
  if (!Number.isSafeInteger(value)) invalid();
  const [mantissa, exponent = '0'] = token.toLowerCase().split('e');
  const [whole, fraction = ''] = mantissa.split('.');
  const scale = Number(exponent) - fraction.length;
  if (Math.abs(scale) > 1000) invalid(); // Bounded parsing, not arbitrary-precision ID support.
  const digits = BigInt(whole + fraction), power = 10n ** BigInt(Math.abs(scale));
  if (scale < 0 && (digits % power !== 0n || digits / power !== BigInt(value))) invalid();
  if (scale >= 0 && digits * power !== BigInt(value)) invalid();
}
checkValue(tool.inputSchema, args);
return [{ json: { tool_name: tool.name, tool_arguments: args } }];

const result = $input.first().json;
if (result.error || result.isError === true || (!result.content && !result.structuredContent)) {
  return [{ json: { error: { code: 'MCP_UNAVAILABLE', message: 'JEMS tool is unavailable.' } } }];
}
return [{ json: { ...(result.content ? { content: result.content } : {}), ...(result.structuredContent ? { structuredContent: result.structuredContent } : {}) } }];
